def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    ERR_DIV = "#DIV/0!"
    ERR_CYCLE = "#CYCLE!"

    def tokenize(text):
        pattern = re.compile(
            r"\s*(?:(\d+)|([A-Z][1-9]\d?)|(<>|<=|>=|[=+\-*/<>():,])|([A-Z]+))"
        )
        tokens = []
        pos = 0
        while pos < len(text):
            match = pattern.match(text, pos)
            if not match:
                raise ValueError("Invalid formula")
            number, cell, symbol, word = match.groups()
            tokens.append(number or cell or symbol or word)
            pos = match.end()
        return tokens

    state = {}
    values = {}

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if state.get(name) == 1:
            return ERR_CYCLE
        if state.get(name) == 2:
            return values[name]

        state[name] = 1
        content = cells[name]
        if not content.startswith("="):
            value = int(content)
        else:
            parser = Parser(tokenize(content[1:]), evaluate_cell)
            value = parser.parse()
        state[name] = 2
        values[name] = value
        return value

    class Parser:
        def __init__(self, tokens, resolve):
            self.tokens = tokens
            self.pos = 0
            self.resolve = resolve

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def take(self):
            token = self.peek()
            self.pos += 1
            return token

        def parse(self):
            return self.expression()

        def expression(self):
            value = self.term()
            while self.peek() in ("+", "-"):
                op = self.take()
                if isinstance(value, str):
                    return value
                right = self.term()
                if isinstance(right, str):
                    return right
                value = value + right if op == "+" else value - right
            return value

        def term(self):
            value = self.unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                if isinstance(value, str):
                    return value
                right = self.unary()
                if isinstance(right, str):
                    return right
                if op == "*":
                    value *= right
                elif right == 0:
                    return ERR_DIV
                else:
                    quotient = abs(value) // abs(right)
                    value = -quotient if (value < 0) != (right < 0) else quotient
            return value

        def unary(self):
            if self.peek() == "-":
                self.take()
                value = self.unary()
                return value if isinstance(value, str) else -value
            return self.atom()

        def atom(self):
            token = self.take()
            if token == "(":
                value = self.expression()
                self.take()  # )
                return value
            if token.isdigit():
                return int(token)
            if token in ("SUM", "MIN", "MAX"):
                return self.aggregate(token)
            if token == "IF":
                return self.conditional()
            if token and token[0].isalpha() and token[0].isupper():
                return self.resolve(token)
            raise ValueError("Invalid formula")

        def conditional(self):
            self.take()  # (
            left = self.expression()
            op = self.take()
            right = self.expression()
            self.take()  # ,
            if isinstance(left, str):
                self.expression()
                self.take()  # ,
                self.expression()
                self.take()  # )
                return left
            if isinstance(right, str):
                self.expression()
                self.take()  # ,
                self.expression()
                self.take()  # )
                return right

            self.take()  # then expression starts here
            then_value = self.expression()
            self.take()  # ,
            else_value = self.expression()
            self.take()  # )

            conditions = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }
            return then_value if conditions[op] else else_value

        def aggregate(self, function):
            self.take()  # (
            values = []
            while True:
                first = self.expression()
                if self.peek() == ":":
                    self.take()
                    second = self.expression()
                    if isinstance(first, str):
                        return first
                    if isinstance(second, str):
                        return second
                    col1, row1 = ord(first[0]) - 65, int(first[1:])
                    col2, row2 = ord(second[0]) - 65, int(second[1:])
                    for row in range(min(row1, row2), max(row1, row2) + 1):
                        for col in range(min(col1, col2), max(col1, col2) + 1):
                            name = chr(65 + col) + str(row)
                            if name in cells:
                                value = self.resolve(name)
                                if isinstance(value, str):
                                    return value
                                values.append(value)
                else:
                    if isinstance(first, str):
                        return first
                    values.append(first)

                if self.peek() == ",":
                    self.take()
                    continue
                self.take()  # )
                break

            if function == "SUM":
                return sum(values)
            if not values:
                return 0
            return min(values) if function == "MIN" else max(values)

    result = {}
    for name in cells:
        result[name] = evaluate_cell(name)
    return result
